export const getGetConsumptionHistoryUrl = (params: GetConsumptionHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/grafana/consumption-history?${stringifiedParams}` : `/api/grafana/consumption-history`
}

